<?php require_once __DIR__.'/database.php';class AppointmentModel{private PDO $db;function __construct(){$this->db=Database::get();}function slot($d,$date,$time){$s=$this->db->prepare("SELECT COUNT(*) FROM appointments WHERE doctor_id=? AND appointment_date=? AND appointment_time=? AND status NOT IN('cancelled','no-show')");$s->execute([$d,$date,$time]);return !$s->fetchColumn();}function serial($d,$date){$s=$this->db->prepare('SELECT COALESCE(MAX(serial_no),0)+1 FROM appointments WHERE doctor_id=? AND appointment_date=?');$s->execute([$d,$date]);return (int)$s->fetchColumn();}function create($p,$d,$date,$time,$source='online'){if(!$this->slot($d,$date,$time))return false;$s=$this->db->prepare("INSERT INTO appointments(patient_id,doctor_id,appointment_date,appointment_time,serial_no,source,status) VALUES(?,?,?,?,?,?, 'pending')");return $s->execute([$p,$d,$date,$time,$this->serial($d,$date),$source]);}function patient($p){$s=$this->db->prepare("SELECT a.*,u.name doctor_name,d.specialization,p.name department_name FROM appointments a JOIN doctors d ON d.id=a.doctor_id JOIN users u ON u.id=d.user_id JOIN departments p ON p.id=d.department_id WHERE a.patient_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC");$s->execute([$p]);return $s->fetchAll();}function doctor($d,$date){$s=$this->db->prepare("SELECT a.*,u.name patient_name,u.phone patient_phone FROM appointments a JOIN users u ON u.id=a.patient_id WHERE a.doctor_id=? AND a.appointment_date=? ORDER BY a.appointment_time,a.serial_no");$s->execute([$d,$date]);return $s->fetchAll();}function all($date=null,$doctor=null){$q="SELECT a.*,p.name patient_name,du.name doctor_name,dep.name department_name FROM appointments a JOIN users p ON p.id=a.patient_id JOIN doctors d ON d.id=a.doctor_id JOIN users du ON du.id=d.user_id JOIN departments dep ON dep.id=d.department_id WHERE 1=1";$x=[];if($date){$q.=' AND a.appointment_date=?';$x[]=$date;}if($doctor){$q.=' AND a.doctor_id=?';$x[]=$doctor;}$q.=' ORDER BY a.appointment_date DESC,a.appointment_time,a.serial_no';$s=$this->db->prepare($q);$s->execute($x);return $s->fetchAll();}function status($id,$v){$s=$this->db->prepare('UPDATE appointments SET status=? WHERE id=?');return $s->execute([$v,$id]);}function cancel($id,$p){$s=$this->db->prepare("UPDATE appointments SET status='cancelled' WHERE id=? AND patient_id=? AND status='pending'");return $s->execute([$id,$p]);}function complete($id,$d,$diag,$note){$s=$this->db->prepare("UPDATE appointments SET status='completed',diagnosis=?,visit_note=? WHERE id=? AND doctor_id=?");return $s->execute([$diag,$note,$id,$d]);}}
?>